Olá! Compreendo perfeitamente o seu objetivo. Você deseja transformar um sistema estático (onde os dados eram hard-coded) em um sistema dinâmico gerenciado por uma área administrativa restrita, utilizando a arquitetura existente do seu projeto Java Swing.

Abaixo, apresento uma solução completa e estruturada para atender aos seus requisitos:

1.  **Autenticação Restrita:** Verificação específica para `admin@admin.com` / `abracadabra`.
2.  **Tela Admin Secreta:** Uma nova classe `TelaAdmin` que só aparece após o login correto.
3.  **Gestão de Entidades:** Integração com `CursoManager` e `QuestionarioManager` para adicionar/remover/visualizar.
4.  **Atualização da Classe Principal:** Modificações na `TelaUsuario` para redirecionar administradores para a tela correta.

---

### 1. Implementação da Autenticação Especializada

Primeiro, precisamos garantir que o método `loginUser` verifique se o usuário é o administrador antes de prosseguir. Isso pode ser feito diretamente no código existente ou adicionando uma lógica condicional. Vou sugerir adicionar uma verificação explícita no fluxo de login dentro da `TelaUsuario`.

### 2. Nova Classe: `TelaAdmin.java`

Esta classe será responsável pela interface gráfica secreta. Ela conterá menus separados para Cursos e Questões, além de botões para Adicionar, Remover e Listar.

```java
package view;

import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.util.Map;

import business.control.CursoManager;
import business.control.QuestionarioManager;
import infra.InfraException;
import util.LoginInvalidException;

public class TelaAdmin extends JFrame {
    private CursoManager cursoManager;
    private QuestionarioManager questionarioManager;
    private boolean isAdminMode = false; // Controle simples de estado visual se necessário

    public TelaAdmin() throws InfraException, LoginInvalidException {
        super("Área Administrativa - SouUFPB", true); // true para sempre visível
        setLayout(new BorderLayout());
        setSize(800, 600);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        initManagers();
        createUI();
    }

    private void initManagers() throws InfraException {
        try {
            cursoManager = new CursoManager();
            questionarioManager = new QuestionarioManager();
        } catch (InfraException e) {
            throw new LoginInvalidException("Erro ao inicializar managers: " + e.getMessage());
        }
    }

    private void createUI() {
        JPanel mainPanel = new JPanel(new BorderLayout(10, 10));
        mainPanel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        // Painel de Seleção Inicial
        JPanel selectionPanel = new JPanel(new GridLayout(1, 2));
        JButton btnCursos = new JButton("Gerenciar Cursos");
        JButton btnQuestoes = new JButton("Gerenciar Questões");

        btnCursos.addActionListener(e -> loadCursosList());
        btnQuestoes.addActionListener(e -> loadQuestionariosList());

        selectionPanel.add(btnCursos);
        selectionPanel.add(btnQuestoes);

        // Área de Conteúdo Dinâmica
        JPanel contentPanel = new JPanel(new BorderLayout());
        JTextArea logArea = new JTextArea("");
        logArea.setEditable(false);
        logArea.setFont(new Font("Monospaced", Font.PLAIN, 12));
        JScrollPane scrollPane = new JScrollPane(logArea);

        contentPanel.add(scrollPane, BorderLayout.CENTER);

        mainPanel.add(selectionPanel, BorderLayout.NORTH);
        mainPanel.add(contentPanel, BorderLayout.CENTER);

        add(mainPanel);
        setVisible(true);
    }

    private void loadCursosList() {
        clearLog();
        String msg = "\n=== LISTAGEM DE CURSOS ===\n";

        try {
            Map<String, Curso> cursos = cursoManager.getCursos();
            if (cursos.isEmpty()) {
                msg += "Nenhum curso cadastrado.\n";
            } else {
                for (String nome : cursos.keySet()) {
                    msg += "- " + cursos.get(nome).getNome() + " (" + cursos.get(nome).getCidade() + ")\n";
                }
            }
            addLog(msg);

            // Simulação de botão de ação (em um app real, aqui entraria num submenu de editar)
            JOptionPane.showMessageDialog(this, "Lista carregada. Use as opções abaixo para gerenciar.", "Sucesso", JOptionPane.INFORMATION_MESSAGE);
        } catch (InfraException e) {
            addLog("Erro ao carregar cursos: " + e.getMessage());
        }
    }

    private void loadQuestionariosList() {
        clearLog();
        String msg = "\n=== LISTAGEM DE QUESTÕES ===\n";

        try {
            Map<String, Questionario> questoes = questionarioManager.getQuestionarios();
            if (questoes.isEmpty()) {
                msg += "Nenhuma questão cadastrada.\n";
            } else {
                for (String pergunta : questoes.keySet()) {
                    msg += "- " + questoes.get(pergunta).getPergunta() + " (" + questoes.get(pergunta).getArea() + ")\n";
                }
            }
            addLog(msg);
            JOptionPane.showMessageDialog(this, "Lista carregada.", "Sucesso", JOptionPane.INFORMATION_MESSAGE);
        } catch (InfraException e) {
            addLog("Erro ao carregar questões: " + e.getMessage());
        }
    }

    // Métodos auxiliares para UI
    private void addLog(String text) {
        SwingUtilities.invokeLater(() -> {
            logArea.append(text);
            logArea.setCaretPosition(logArea.getDocument().getLength());
        });
    }

    private void clearLog() {
        SwingUtilities.invokeLater(() -> logArea.setText(""));
    }

    // Exemplos de ações futuras (Adicionar/Remover via Dialogs)
    private void handleAddRemoveAction(JButton button, String[] args, String actionName) {
        try {
            if (args.length == 0) {
                JOptionPane.showMessageDialog(this, "Selecione a opção de adição/remoção no menu detalhado.");
                return;
            }
            // Lógica de execução dependendo do tipo de entidade
            if (actionName.equals("curso")) {
                cursoManager.adicionarCurso(args);
            } else if (actionName.equals("questao")) {
                questionarioManager.adicionarQuestionario(args[0], args[1]);
            }
            addLog("Ação bem-sucedida: " + actionName);
        } catch (InfraException | IllegalArgumentException e) {
            addLog("Erro: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        // Configuração básica para Swing em ambiente desktop
        UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());

        try {
            Runnable r = () -> {
                try {
                    new TelaAdmin().setVisible(true);
                } catch (Exception e) {
                    JOptionPane.showMessageDialog(null, "Falha ao iniciar a tela admin: " + e.getMessage(), "Erro", JOptionPane.ERROR_MESSAGE);
                    System.exit(1);
                }
            };
            Thread t = new Thread(r);
            t.start();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

### 3. Atualização da Classe Principal: `TelaUsuario.java`

Aqui faremos duas alterações principais:
1.  No método `loginUser`, verificaremos se o email é o do administrador. Se for, direcionará para a `TelaAdmin`.
2.  O método `showMenuApp` já deve verificar se o usuário é admin para decidir qual menu mostrar.

```java
package view;

import javax.swing.JOptionPane;
import business.control.UserManager;
import util.EmailInvalidException;
import util.LoginInvalidException;
import util.PasswordInvalidException;
import util.LoginValidator;
import javax.swing.*;
import java.util.logging.Logger;

public class TelaUsuario {
    private UserManager userManager;
    private static TelaUsuario instance = null;
    private LoginValidator loginValidator;

    // Constante para o admin
    private static final String ADMIN_EMAIL = "admin@admin.com";
    private static final String ADMIN_PASS = "abracadabra";

    private TelaUsuario() throws InfraException{
        this.loginValidator = new LoginValidator();
    }

    public static void main (String[] args) throws LoginInvalidException, InfraException {
        showMenuLogin();
    }

    public static void showMenuLogin() throws LoginInvalidException, InfraException {
        TelaUsuario main = getInstance();
        String option = JOptionPane.showInputDialog("Olá usuário, bem vindo ao SouUFPB\nEscolha a opcao desejada:\n1-Se cadastrar\n2-Logar\n3-Sair","Sua opcao");     

        main.readUserInputLogin(option);
    }

    public static void showMenuApp(String email) throws InfraException {
        // Verifica se é admin antes de mostrar o menu comum
        if (ADMIN_EMAIL.equals(email)) {
            // Se for admin, abre a tela de gestão
            try {
                new TelaAdmin().setVisible(true);
                System.exit(0); // Fecha a aplicação principal após abrir o admin
            } catch (Exception e) {
                JOptionPane.showMessageDialog(null, "Erro ao acessar área administrativa: " + e.getMessage());
                showMenuApp(email); // Tenta de novo caso falhe
            }
            return;
        }

        // Menu normal para usuários comuns
        String option = JOptionPane.showInputDialog("Escolha a opcao desejada:\n1-Ver os Cursos da UFPB\n2-Fazer teste vocacional\n3-Sair","Sua opcao");

        TelaUsuario secondmain = new TelaUsuario();
        secondmain.readUserInputApp(option, email);
    }

    private void readUserInputApp(String option, String email) throws InfraException {
        int choice = Integer.parseInt(option);
        switch (choice) {
            case 1:
                Cursos.entraremcursos();
                break;
            case 2:
                Testes.questionario(email);
                break;
            case 3:
                System.exit(0);
                break;
            default:
                JOptionPane.showMessageDialog(null, "Opção inválida!");
                showMenuApp(email);
                break;
        }
    }

    public void readUserInputLogin(String option) throws LoginInvalidException, InfraException {
        try {
            userManager = new UserManager();
        } catch (InfraException e) {
            String option2 = JOptionPane.showInputDialog(e.getMessage());
        }
        int choice = Integer.parseInt(option);
        switch (choice) {

            case 1:
                registerUser();
                showMenuLogin();
                break;

            case 2: 
