                }
            }
            addLog(msg);
            JOptionPane.showMessageDialog(this, "Lista carregada.", "Sucesso", JOptionPane.INFORMATION_MESSAGE);
        } catch (InfraException e) {
            addLog("Erro ao carregar questões: " + e.getMessage());
        }
    }

    // Métodos auxiliares para UI
    private void addLog(String text) {
        SwingUtilities.invokeLater(() -> {
            logArea.append(text);
            logArea.setCaretPosition(logArea.getDocument().getLength());
        });
    }

